* { box-sizing: border-box; }
body { margin: 0; background: #f4f6f8; color: #182230; font: 16px/1.5 system-ui, sans-serif; }
.container { width: min(760px, calc(100% - 32px)); margin: 56px auto; padding: 32px; background: white; border: 1px solid #e1e6eb; border-radius: 12px; box-shadow: 0 8px 28px #1522380c; }
h1 { margin: 0 0 24px; font-size: 2rem; }
label { display: block; margin-bottom: 8px; font-weight: 600; }
.form-row, .project-row { display: flex; align-items: center; gap: 12px; }
input { flex: 1; min-width: 0; height: 42px; padding: 8px 12px; border: 1px solid #aeb9c5; border-radius: 6px; font: inherit; }
button { min-height: 40px; padding: 8px 16px; border: 0; border-radius: 6px; background: #175cd3; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #1249ad; }
.project-row { justify-content: space-between; margin-top: 16px; padding: 14px 16px; border: 1px solid #dce2e8; border-radius: 8px; }
#back-button { margin-bottom: 24px; background: #475467; }
#notice:not([hidden]) { margin-bottom: 18px; padding: 12px 14px; border: 1px solid #fda29b; border-radius: 6px; background: #fef3f2; color: #b42318; }
[hidden] { display: none !important; }
